pug:
table.row.white-bg.b-system-text-62
    tr
        td.wrapper.last
            table.twelve.columns
                tr
                    td.plr30.pb30
                        .blue-block
                            p.text.center {{ text_1 }}
                            p.text.icon-text.icon-text_1 {{ text_2 }}
                            p.text.icon-text.icon-text_2 {{ text_3 }}
                            p.text.center {{ text_4 }}

styl:
.white-bg.b-system-text-62 {  background:#fff  }
.b-system-text-62 .text {  font-family:Arial!important;color:#5b6e88;font-size:16px;font-weight:400;line-height:26px;padding-bottom:20px  }
@media screen and (max-width:600px) {
  .b-system-text-62 .text {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-62 .grey-text a, .b-system-text-62 .text a {  color:#0b8bd8;text-decoration:underline  }
.b-system-text-62 .icon-text {  padding-left:80px  }
@media screen and (max-width:600px) {
  .b-system-text-62 .icon-text {  padding-left:50px!important  }
}
.b-system-text-62 .icon-text_1 {  background:url(https://images01.iqoption.com/57/5857/static-02566133645999865857.png) left top 10px no-repeat;background-size:53px auto  }
@media screen and (max-width:600px) {
  .b-system-text-62 .icon-text_1 {  background-size:40px auto!important  }
}
.b-system-text-62 .icon-text_2 {  background:url(https://images01.iqoption.com/89/3089/static-03344689742204633089.png) left top 10px no-repeat;background-size:42px auto  }
@media screen and (max-width:600px) {
  .b-system-text-62 .icon-text_2 {  background-size:35px auto!important  }
}
.b-system-text-62 .text.bold {  font-weight:700  }
.b-system-text-62 .plr30 {  padding-left:30px;padding-right:30px  }
@media screen and (max-width:600px) {
  .b-system-text-62 .plr30 {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-62 .blue-block {  background:#f7fbff;border-radius:7px;padding:20px  }
@media screen and (max-width:600px) {
  .b-system-text-62 .blue-block {  padding-left:15px!important;padding-right:15px!important  }
}
